-- 第 4 周：MySQL BI 集市初始化脚本
-- 由 sync/sync_ads_to_mysql.py 自动生成，数据来源：Hive 的 ydsh_ads / ydsh_dws
-- 执行方式：docker exec -i hive-project-mysql-1 mysql -uroot -proot < init_ydsh_ads.sql

CREATE DATABASE IF NOT EXISTS ydsh_ads DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ydsh_ads;
SET NAMES utf8mb4;

-- ---------- ads_kpi_overview（6 行） ----------
DROP TABLE IF EXISTS `ads_kpi_overview`;
CREATE TABLE `ads_kpi_overview` (
  `kpi_name` VARCHAR(64),
  `kpi_value` DECIMAL(18,2),
  `kpi_unit` VARCHAR(16),
  `definition` VARCHAR(255)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- ads_sales_daily（366 行） ----------
DROP TABLE IF EXISTS `ads_sales_daily`;
CREATE TABLE `ads_sales_daily` (
  `stat_date` DATE,
  `order_cnt` BIGINT,
  `gmv` DECIMAL(18,2),
  `aov` DECIMAL(12,2),
  `gmv_dod` DECIMAL(10,4),
  `gmv_ma7` DECIMAL(18,2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- ads_category_topn（8 行） ----------
DROP TABLE IF EXISTS `ads_category_topn`;
CREATE TABLE `ads_category_topn` (
  `rk` INT,
  `category` VARCHAR(64),
  `order_cnt` BIGINT,
  `qty` BIGINT,
  `sales` DECIMAL(18,2),
  `sales_ratio` DECIMAL(10,4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- ads_store_topn（60 行） ----------
DROP TABLE IF EXISTS `ads_store_topn`;
CREATE TABLE `ads_store_topn` (
  `rk` INT,
  `store_id` VARCHAR(32),
  `store_name` VARCHAR(64),
  `province` VARCHAR(32),
  `city` VARCHAR(32),
  `order_cnt` BIGINT,
  `gmv` DECIMAL(18,2),
  `aov` DECIMAL(12,2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- ads_user_value（1000 行） ----------
DROP TABLE IF EXISTS `ads_user_value`;
CREATE TABLE `ads_user_value` (
  `user_id` VARCHAR(32),
  `total_amount` DECIMAL(18,2),
  `order_cnt` BIGINT,
  `last_order` DATE,
  `value_level` VARCHAR(32)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- dws_sales_month（12 行） ----------
DROP TABLE IF EXISTS `dws_sales_month`;
CREATE TABLE `dws_sales_month` (
  `stat_month` VARCHAR(16),
  `order_cnt` BIGINT,
  `gmv` DECIMAL(18,2),
  `buyer_cnt` BIGINT,
  `aov` DECIMAL(12,2),
  `cancel_rate` DECIMAL(10,4),
  `refund_rate` DECIMAL(10,4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- dws_category_month（96 行） ----------
DROP TABLE IF EXISTS `dws_category_month`;
CREATE TABLE `dws_category_month` (
  `stat_month` VARCHAR(16),
  `category` VARCHAR(64),
  `order_cnt` BIGINT,
  `qty` BIGINT,
  `sales` DECIMAL(18,2),
  `sales_ratio` DECIMAL(10,4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- dws_store_month（720 行） ----------
DROP TABLE IF EXISTS `dws_store_month`;
CREATE TABLE `dws_store_month` (
  `stat_month` VARCHAR(16),
  `store_id` VARCHAR(32),
  `store_name` VARCHAR(64),
  `province` VARCHAR(32),
  `city` VARCHAR(32),
  `order_cnt` BIGINT,
  `gmv` DECIMAL(18,2),
  `buyer_cnt` BIGINT,
  `aov` DECIMAL(12,2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- dws_channel_month（48 行） ----------
DROP TABLE IF EXISTS `dws_channel_month`;
CREATE TABLE `dws_channel_month` (
  `stat_month` VARCHAR(16),
  `channel_code` VARCHAR(16),
  `channel_name` VARCHAR(32),
  `order_cnt` BIGINT,
  `gmv` DECIMAL(18,2),
  `buyer_cnt` BIGINT,
  `aov` DECIMAL(12,2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------- 校验 ----------
SELECT 'ads_kpi_overview' AS tbl, COUNT(*) AS cnt FROM `ads_kpi_overview`;
SELECT 'ads_sales_daily' AS tbl, COUNT(*) AS cnt FROM `ads_sales_daily`;
SELECT 'ads_category_topn' AS tbl, COUNT(*) AS cnt FROM `ads_category_topn`;
SELECT 'ads_store_topn' AS tbl, COUNT(*) AS cnt FROM `ads_store_topn`;
SELECT 'ads_user_value' AS tbl, COUNT(*) AS cnt FROM `ads_user_value`;
SELECT 'dws_sales_month' AS tbl, COUNT(*) AS cnt FROM `dws_sales_month`;
SELECT 'dws_category_month' AS tbl, COUNT(*) AS cnt FROM `dws_category_month`;
SELECT 'dws_store_month' AS tbl, COUNT(*) AS cnt FROM `dws_store_month`;
SELECT 'dws_channel_month' AS tbl, COUNT(*) AS cnt FROM `dws_channel_month`;
